INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q1373706', 'Ayutthayan–Cambodian War', 'The Siamese–Cambodian War (1591–1594) (Khmer: សង្គ្រាមសៀម-កម្ពុជា (១៥៩១-១៥៩៤); Thai: สงครามสยาม-กัมพูชา พ.ศ. 2134), also known as The Siamese Invasion of Longvek, was a military conflict fought between the Ayutthaya Kingdom and the Kingdom of Cambodia.', 1591, NULL, NULL, 1594, 1, 3, 'year', '1591 – 3 January 1594', 43, 'https://en.wikipedia.org/wiki/Siamese%E2%80%93Cambodian_War_(1591%E2%80%931594)'),
  ('Q27627985', 'Cambodian–Spanish War', 'The Cambodian–Spanish War (Spanish: Guerra Ibero-Camboyana; Filipino: Digmaang Kambodyano-Espanyol; Khmer: សង្គ្រាមកម្ពុជា-អេស្ប៉ាញ) (1593–1599) was an attempt to conquer Cambodia on behalf of King Satha I and Christianize Cambodia''s population by the Spanish and Portuguese Empires. Along with the Spanish, Filipinos, Mexican recruits, Japanese mercenaries participated in the invasion of Cambodia.', 1593, NULL, NULL, 1597, NULL, NULL, 'year', '1593–1597', 37, 'https://en.wikipedia.org/wiki/Cambodian%E2%80%93Spanish_War'),
  ('Q17048924', 'Cambodian–Dutch War', 'The Cambodian–Dutch War (Dutch: Cambodjaans-Nederlandse Oorlog; Khmer: សង្គ្រាមកម្ពុជា-ហូឡង់) from 1642–1644 was a conflict sparked by a coup which brought a new Cambodian king to the throne who converted to Islam with the help of Malay traders resident in the country. The sultan initiated a massacre of Dutch East India Company employees and subsequently defeated the Dutch forces sent to extract retribution from the Cambodians.', 1643, NULL, NULL, 1644, NULL, NULL, 'year', '1643–1644', 48, 'https://en.wikipedia.org/wiki/Cambodian%E2%80%93Dutch_War'),
  ('Q2280725', 'Siamese–Vietnamese War of 1771-1773', 'The Siamese–Vietnamese War (1771–1773) was a war between Siam (modern Thailand) of the Thonburi Period in the reign of King Taksin and the Nguyễn Lords of Cochinchina or Southern Vietnam. The war also involved Cambodia and the Hà Tiên polity, which were allies of the Nguyen Lord.', 1771, 10, NULL, 1773, 3, NULL, 'month', 'October 1771 – March 1773', 37, 'https://en.wikipedia.org/wiki/Siamese%E2%80%93Vietnamese_War_(1771%E2%80%931773)'),
  ('Q3381219', 'Siamese–Vietnamese War of 1831-1834', 'The Siamese–Vietnamese War of 1833–1834 (Thai: อานามสยามยุทธ (พ.ศ. 2376 – พ.ศ.', 1831, NULL, NULL, 1834, NULL, NULL, 'year', '1831–1834', 45, 'https://en.wikipedia.org/wiki/Siamese%E2%80%93Vietnamese_War_(1833%E2%80%931834)'),
  ('Q641185', 'Siamese–Vietnamese War of 1841–1845', 'The Siamese–Vietnamese War of 1840–1845 (Thai: อานามสยามยุทธ (พ.ศ. 2383 – พ.ศ.', 1841, NULL, NULL, 1845, NULL, NULL, 'year', '1841–1845', 45, 'https://en.wikipedia.org/wiki/Siamese%E2%80%93Vietnamese_War_(1840%E2%80%931845)'),
  ('Q4919422', 'Japanese occupation of Cambodia', 'The Japanese occupation of Cambodia (Khmer: ការត្រួតត្រារបស់ជប៉ុននៅកម្ពុជា) was the period of Cambodian history during World War II when the Kingdom of Cambodia was occupied by the Japanese. Vichy France, which was a client state of Germany, nominally maintained the French protectorate over Cambodia and other parts of Indochina during most of the Japanese occupation.', 1941, NULL, NULL, 1945, NULL, NULL, 'year', '1941–1945', 56, 'https://en.wikipedia.org/wiki/Japanese_occupation_of_Cambodia'),
  ('Q4872904', 'Battle of the Day River', 'The Battle of the Day River (French: bataille du Day) took place between late May and early June 1951, around the Day River Delta in the Gulf of Tonkin. Part of the First Indochina War, the battle was the first conventional campaign of Võ Nguyên Giáp, and saw his Việt Minh People''s Army of Vietnam (VPA) forces tackle the Catholic-dominated region of the Delta in order to break its resistance to communist Việt Minh infiltration.', 1951, 6, 18, NULL, NULL, NULL, 'day', '18 June 1951', 37, 'https://en.wikipedia.org/wiki/Battle_of_the_Day_River'),
  ('Q817206', 'Cambodian Civil War', 'The Cambodian Civil War (Khmer: សង្គ្រាមស៊ីវិលកម្ពុជា, UNGEGN: Sângkréam Sĭvĭl Kâmpŭchéa) was a civil war in Cambodia fought by the Khmer Rouge against the government of the Kingdom of Cambodia. Following the March 1970 coup, the conflict shifted as the Khmer Rouge and forces loyal to Norodom Sihanouk, now supported by North Vietnam and China, fought against the Khmer Republic, which was supported by the United States and South Vietnam.', 1967, 3, 11, 1975, 4, 17, 'day', '11 March 1967 – 17 April 1975', 72, 'https://en.wikipedia.org/wiki/Cambodian_Civil_War'),
  ('Q683271', 'Operation Menu', 'Operation Menu was a covert United States Strategic Air Command (SAC) tactical bombing campaign conducted in eastern Cambodia from 18 March 1969 to 26 May 1970 as part of the Vietnam War. The targets of these attacks were sanctuaries and base areas of the People''s Army of Vietnam (PAVN – commonly referred to during the war as the North Vietnamese Army, NVA) and the Viet Cong (VC), which used them for resupply, training, and resting between campaigns across the border in the Republic of Vietnam (South Vietnam).', 1969, 3, 18, 1970, 5, 26, 'day', '18 March 1969 – 26 May 1970', 51, 'https://en.wikipedia.org/wiki/Operation_Menu'),
  ('Q4919446', '1970 Cambodian coup d''état', 'A coup d''état removed the Cambodian chief of state, Prince Norodom Sihanouk, after a vote in the National Assembly on 18 March 1970. Emergency powers were subsequently invoked by the Prime Minister Lon Nol, who became effective head of state, and led ultimately to the removal of Queen Sisowath Kossamak and the proclamation of the Khmer Republic later that year.', 1970, 3, 18, NULL, NULL, NULL, 'day', '18 March 1970', 56, 'https://en.wikipedia.org/wiki/1970_Cambodian_coup_d''%C3%A9tat'),
  ('Q4871377', 'Battle of Kampot', 'The Battle of Kampot was a major military engagement of the Vietnam War, also a part of the Cambodian Civil War, fought between 26 February to 2 April 1974, in which Cambodian Army troops loyal to the Khmer Republic battled Khmer Rouge guerillas for the control of Kampot, the second seaport city of southern Cambodia and capital of Kampot province.', 1974, 2, 26, 1974, 4, 2, 'day', '26 February 1974 – 2 April 1974', 34, 'https://en.wikipedia.org/wiki/Battle_of_Kampot'),
  ('Q796498', 'Third Indochina War', 'The Third Indochina War was a series of interconnected military conflicts among the various communist factions over strategic influence in mainland Southeast Asia after communist victory in South Vietnam, Laos, and Cambodia in 1975. The conflict primarily started due to continued raids and incursions by the Khmer Rouge into Vietnamese territory that they sought to retake.', 1975, 5, 1, 1991, 10, 23, 'day', '1 May 1975 – 23 October 1991', 53, 'https://en.wikipedia.org/wiki/Third_Indochina_War'),
  ('Q85760415', 'Fall of Phnom Penh', 'The Fall of Phnom Penh was the capture of Phnom Penh, capital of the Khmer Republic (in present-day Cambodia), by the Khmer Rouge on 17 April 1975, effectively ending the Cambodian Civil War. At the beginning of the month, Phnom Penh, one of the last remaining strongholds of the Khmer Republic, was surrounded by the Khmer Rouge and totally dependent on aerial resupply through Pochentong Airport.', 1975, 4, 17, NULL, NULL, NULL, 'day', '17 April 1975', 51, 'https://en.wikipedia.org/wiki/Fall_of_Phnom_Penh'),
  ('Q114658776', 'Dangrek genocide', 'The Dangrek Incident, also known as the Preah Vihear Massacre, or Preah Vihear massacre, was the June 1979 systematic, forced repatriation of 42,000–45,000 Cambodian refugees (mostly women and children) by the Thai military. It resulted in from 3,000 to over 10,000 deaths from landmines, shootings, falls off cliffs, exposure, and disease.', 1979, 6, 8, NULL, NULL, NULL, 'day', '8 June 1979', 34, 'https://en.wikipedia.org/wiki/Dangrek_Incident'),
  ('Q846291', 'Vietnam Airlines Flight 815', 'Vietnam Airlines Flight 815 was a scheduled Vietnam Airlines flight which crashed on final approach to Pochentong International Airport in Cambodia on 3 September 1997. The Soviet-built Tupolev Tu-134 airliner crashed approximately 800 metres (2,600 ft; 870 yd) short of the Phnom Penh runway, killing 65 of the 66 people on board.', 1997, 9, 3, NULL, NULL, NULL, 'day', '3 September 1997', 53, 'https://en.wikipedia.org/wiki/Vietnam_Airlines_Flight_815'),
  ('Q4601739', '2003 Phnom Penh riots', 'In January 2003, a Cambodian newspaper article falsely alleged that Thai actress Suvanant Kongying claimed that the Angkor Wat belonged to Thailand. Other Cambodian print and radio media picked up the report and furthered nationalistic sentiments, which resulted in riots in Phnom Penh on 29 January where the Thai embassy was burned and commercial properties of Thai businesses were vandalized.', 2003, NULL, NULL, NULL, NULL, NULL, 'year', '2003', 45, 'https://en.wikipedia.org/wiki/2003_Phnom_Penh_riots'),
  ('Q15529576', '2013–2014 Cambodian protests', 'Anti-government protests (Khmer: បាតុកម្មប្រឆាំងរាជរដ្ឋាភិបាល) took place in Cambodia from July 2013 to July 2014. Popular demonstrations in Phnom Penh took place against the government of Prime Minister Hun Sen, triggered by widespread allegations of electoral fraud during the 2013 general election.', 2013, 7, 28, NULL, NULL, NULL, 'day', '28 July 2013', 41, 'https://en.wikipedia.org/wiki/2013%E2%80%932014_Cambodian_protests'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q136659001', 'Kuala Lumpur Peace Accord', 'The Kuala Lumpur Peace Accord (officially the Joint Declaration by the Prime Minister of the Kingdom of Cambodia and the Prime Minister of the Kingdom of Thailand on the Outcomes of Their Meeting in Kuala Lumpur, Malaysia) was a peace agreement signed on 26 October 2025, on the sidelines of the 47th ASEAN Summit at the Kuala Lumpur Convention Centre in Kuala Lumpur, Malaysia. The accord was reached in the aftermath of an escalating border crisis along the Cambodia–Thailand border, which had seen armed clashes, landmine incidents, and heightened military deployments on both sides.', 2025, 10, 26, NULL, NULL, NULL, 'day', '26 October 2025', 41, 'https://en.wikipedia.org/wiki/Kuala_Lumpur_Peace_Accord');
